def create_sql(self, expression: exp.Create) -> str:
    kind = expression.kind
    exists = expression.args.pop("exists", None)

    like_property = expression.find(exp.LikeProperty)
    if like_property:
        ctas_expression = like_property.this
    else:
        ctas_expression = expression.expression

    if kind == "VIEW":
        expression.this.set("catalog", None)
        with_ = expression.args.get("with")
        if ctas_expression and with_:
            # We've already preprocessed the Create expression to bubble up any nested CTEs,
            # but CREATE VIEW actually requires the WITH clause to come after it so we need
            # to amend the AST by moving the CTEs to the CREATE VIEW statement's query.
            ctas_expression.set("with", with_.pop())

    sql = super().create_sql(expression)

    table = expression.find(exp.Table)

    # Convert CTAS statement to SELECT .. INTO ..
    if kind == "TABLE" and ctas_expression:
        if isinstance(ctas_expression, exp.UNWRAPPED_QUERIES):
            ctas_expression = ctas_expression.subquery()

        properties = expression.args.get("properties") or exp.Properties()
        is_temp = any(isinstance(p, exp.TemporaryProperty) for p in properties.expressions)

        select_into = exp.select("*").from_(exp.alias_(ctas_expression, "temp", table=True))
        select_into.set("into", exp.Into(this=table, temporary=is_temp))

        if like_property:
            select_into.limit(0, copy=False)

        sql = self.sql(select_into)

    if exists:
        identifier = self.sql(exp.Literal.string(exp.table_name(table) if table else ""))
        sql_with_ctes = self.prepend_ctes(expression, sql)
        sql_literal = self.sql(exp.Literal.string(sql_with_ctes))
        if kind == "SCHEMA":
            return f"""IF NOT EXISTS (SELECT * FROM information_schema.schemata WHERE schema_name = {identifier}) EXEC({sql_literal})"""
        elif kind == "TABLE":
            assert table
            where = self.sql(
                exp.and_(
                    exp.column("table_name").eq(table.name),
                    exp.column("table_schema").eq(table.db) if table.db else None,
                    exp.column("table_catalog").eq(table.catalog) if table.catalog else None,
                )
            )
            return f"""IF NOT EXISTS (SELECT * FROM information_schema.tables WHERE {where}) EXEC({sql_literal})"""
        elif kind == "INDEX":
            index = self.sql(exp.Literal.string(expression.this.text("this")))
            return f"""IF NOT EXISTS (SELECT * FROM sys.indexes WHERE object_id = object_id({identifier}) AND name = {index}) EXEC({sql_literal})"""
    elif expression.args.get("replace"):
        sql = sql.replace("CREATE OR REPLACE ", "CREATE OR ALTER ", 1)

    return self.prepend_ctes(expression, sql)

def datatype_sql(self, expression: exp.DataType) -> str:
    # Check if this is a temporal type that needs precision handling. Fabric limits temporal
    # types to max 6 digits precision. When no precision is specified, we default to 6 digits.
    if expression.is_type(*exp.DataType.TEMPORAL_TYPES):
        # Get the current precision (first expression if it exists)
        precision_param = expression.find(exp.DataTypeParam)

        if precision_param and precision_param.this.is_int:
            current_precision = precision_param.this.to_py()
            if current_precision > 6:
                expression = exp.DataType(
                    this=expression.this,
                    expressions=[exp.DataTypeParam(this=exp.Literal.number(6))],
                )

    return super().datatype_sql(expression)

def _parse_group(self, skip_group_by_token: bool = False) -> t.Optional[exp.Group]:
    if not skip_group_by_token and not self._match(TokenType.GROUP_BY):
        return None
    comments = self._prev_comments

    elements: t.Dict[str, t.Any] = defaultdict(list)

    if self._match(TokenType.ALL):
        elements["all"] = True
    elif self._match(TokenType.DISTINCT):
        elements["all"] = False

    while True:
        index = self._index

        elements["expressions"].extend(
            self._parse_csv(
                lambda: None
                if self._match_set((TokenType.CUBE, TokenType.ROLLUP), advance=False)
                else self._parse_assignment()
            )
        )

        before_with_index = self._index
        with_prefix = self._match(TokenType.WITH)

        if self._match(TokenType.ROLLUP):
            elements["rollup"].append(
                self._parse_cube_or_rollup(exp.Rollup, with_prefix=with_prefix)
            )
        elif self._match(TokenType.CUBE):
            elements["cube"].append(
                self._parse_cube_or_rollup(exp.Cube, with_prefix=with_prefix)
            )
        elif self._match(TokenType.GROUPING_SETS):
            elements["grouping_sets"].append(
                self.expression(
                    exp.GroupingSets,
                    expressions=self._parse_wrapped_csv(self._parse_grouping_set),
                )
            )
        elif self._match_text_seq("TOTALS"):
            elements["totals"] = True  # type: ignore

        if self._index == before_with_index:
            break
        if with_prefix and self._index == before_with_index + 1:
            self._retreat(before_with_index)
            break

        if index == self._index:
            break

    return self.expression(exp.Group, comments=comments, **elements)  # type: ignore

def _parse_for_in(self) -> exp.ForIn:
    this = self._parse_id_var()
    self._match_text_seq("DO")
